"""Generate assets/js/practice-labs/data/pandas-predict.js by running every exercise with the local pandas (2.2.x) and
CPython, so each expected output is a real recorded run. Usage: python scripts/practice-labs/build_pandas_predict.py"""
import os
import json, subprocess, sys
H = 'import pandas as pd\norders = pd.DataFrame({"order": ["SL-1", "SL-2", "SL-3", "SL-4"], "city": ["Pune", "Delhi", "Pune", "Mumbai"], "total": [1299, 499, 2150, 349]})\n'
EX = [
    ("pd-p-shape", H + 'print(orders.shape)\nprint(orders["total"].sum())\nprint(orders["city"].nunique())',
     "shape is (rows, columns); nunique counts distinct values.", "A DataFrame is a table of columns; shape, sum and nunique answer the first questions about any dataset."),
    ("pd-p-filter", H + 'big = orders[orders["total"] > 1000]\nprint(big["order"].tolist())\nprint(len(orders[(orders["city"] == "Pune") & (orders["total"] < 2000)]))',
     "Boolean masks keep the rows where the condition is True; combine them with & and brackets.", "orders[mask] filters rows. Conditions are combined with & (and) and | (or), each in brackets, not with the Python words and/or."),
    ("pd-p-groupby", H + 'by_city = orders.groupby("city")["total"].sum()\nprint(by_city.to_dict())\nprint(by_city.idxmax())',
     "groupby sorts the groups by key by default.", "groupby splits rows by city, sum aggregates each group, and idxmax returns the label of the largest value."),
    ("pd-p-sort-top", H + 'top = orders.sort_values("total", ascending=False).head(2)\nprint(top["order"].tolist())',
     "ascending=False puts the biggest first; head takes the first rows.", "sort_values then head(n) is the idiom for a top-n list."),
    ("pd-p-missing", 'import pandas as pd\ns = pd.Series([10, None, 30])\nprint(s.mean())\nprint(s.isna().sum())\nprint(s.fillna(0).tolist())',
     "Missing values become NaN and are skipped by mean; the Series becomes float.", "pandas skips NaN in aggregates by default, so the mean is of 10 and 30. Filling with 0 changes that mean: decide deliberately."),
    ("pd-p-clean-text", 'import pandas as pd\nnames = pd.Series(["  Asha ", "asha", "RAVI", "Ravi "])\nclean = names.str.strip().str.title()\nprint(clean.unique().tolist())\nprint(clean.value_counts().to_dict())',
     "Strip spaces, then normalise case, then count.", "The .str accessor applies string methods to every value; cleaning before counting merges spellings of the same name."),
    ("pd-p-text-numbers", 'import pandas as pd\ns = pd.Series(["1,299", "499", "2,150"])\nprint(s.dtype)\nnums = s.str.replace(",", "").astype(int)\nprint(nums.sum())',
     "Numbers with commas are read as text (object dtype).", "Imported numbers often arrive as text; remove separators and convert with astype before doing arithmetic."),
    ("pd-p-merge", H + 'cities = pd.DataFrame({"city": ["Pune", "Delhi"], "region": ["West", "North"]})\nm = orders.merge(cities, on="city", how="left")\nprint(m["region"].tolist())\nprint(m["region"].isna().sum())',
     "A left merge keeps every order; cities without a match get NaN.", "merge works like a SQL join. how='left' keeps all orders, and the missing region for Mumbai shows a gap in the lookup table."),
    ("pd-p-dates", 'import pandas as pd\nd = pd.to_datetime(pd.Series(["2026-01-31", "2026-02-15", "2026-03-01"]))\nprint(d.dt.month.tolist())\nprint((d.max() - d.min()).days)\nprint(d.dt.strftime("%b %Y").unique().tolist())',
     "to_datetime parses text into dates; subtracting gives a Timedelta.", "Convert date text with to_datetime, then use the .dt accessor for parts and formatting, and subtraction for durations."),
    ("pd-p-pivot", H + 'orders["size"] = ["big" if t > 1000 else "small" for t in orders["total"]]\np = orders.pivot_table(index="city", columns="size", values="total", aggfunc="count", fill_value=0)\nprint(p.to_dict())',
     "pivot_table counts orders per city and size; fill_value replaces missing combinations.", "pivot_table is the pandas version of a spreadsheet pivot table: index rows, columns, values and an aggregation.")
]
out = []
for i, code, hint, explain in EX:
    r = subprocess.run([sys.executable, "-c", code], capture_output=True, text=True)
    assert r.returncode == 0, (i, r.stderr)
    out.append({"id": i, "lang": "python", "code": code, "output": r.stdout.replace("\r\n", "\n").rstrip("\n"), "hint": hint, "explain": explain,
                "note": "Not executed here: pandas does not run in this page. The expected output was recorded by running the code with pandas 2.2 and CPython."})
js = "/* =========================================================\n   ToolZen Hub\n   Data Analysis with pandas path: output-prediction exercises. pandas is not run in the page (it would need a further\n   large download); every expected output was recorded by running the code with pandas 2.2.3 and CPython, and is\n   re-checked by tests/unit/predict.test.mjs when pandas is installed. Generated by scripts/practice-labs/build_pandas_predict.py.\n========================================================= */\n\nexport const PANDAS_PREDICT = Object.freeze(" + json.dumps(out, ensure_ascii=False, indent=4) + ");\n"
open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "assets", "js", "practice-labs", "data", "pandas-predict.js"), "w", encoding="utf8").write(js)
for o in out: print(o["id"], "=>", o["output"].replace("\n", " | "))
